1	/**
2	 * Cálculos relacionados ao período de experiência (CLT Art. 445/451 + Súmula 188 TST).
3	 */
4	
5	import type { Contrato } from '../types';
6	
7	/** Diferença em dias entre uma data ISO e hoje (positivo = no futuro). */
8	export function diasAteData(dateIso: string | null | undefined): number | null {
9	  if (!dateIso) return null;
10	  const target = new Date(dateIso + 'T00:00:00');
11	  const today = new Date();
12	  today.setHours(0, 0, 0, 0);
13	  const diffMs = target.getTime() - today.getTime();
14	  return Math.round(diffMs / (1000 * 60 * 60 * 24));
15	}
16	
17	/** Próxima data de fim aplicável: prorrogado se houver, senão inicial. */
18	export function proximoFimContrato(c: Contrato): string | null {
19	  if (c.tipo !== 'experiencia') return null;
20	  return c.data_fim_prorrogado ?? c.data_fim_inicial;
21	}
22	
23	/** Status visual baseado em dias restantes. */
24	export type ProbationAlertLevel = 'safe' | 'd30' | 'd15' | 'd7' | 'overdue';
25	
26	export function probationAlertLevel(diasRestantes: number | null): ProbationAlertLevel {
27	  if (diasRestantes === null) return 'safe';
28	  if (diasRestantes < 0) return 'overdue';
29	  if (diasRestantes <= 7) return 'd7';
30	  if (diasRestantes <= 15) return 'd15';
31	  if (diasRestantes <= 30) return 'd30';
32	  return 'safe';
33	}
34	
35	export const PROBATION_ALERT_COLORS: Record<ProbationAlertLevel, string> = {
36	  safe: 'bg-blue-100 text-blue-900 border-blue-200',
37	  d30: 'bg-yellow-100 text-yellow-900 border-yellow-200',
38	  d15: 'bg-orange-100 text-orange-900 border-orange-200',
39	  d7: 'bg-red-100 text-red-900 border-red-300',
40	  overdue: 'bg-red-200 text-red-950 border-red-400',
41	};
42	
43	export function probationAlertText(diasRestantes: number | null): string {
44	  if (diasRestantes === null) return 'Sem data definida';
45	  if (diasRestantes < 0) return `Vencido há ${Math.abs(diasRestantes)} dias`;
46	  if (diasRestantes === 0) return 'Encerra hoje';
47	  if (diasRestantes === 1) return 'Encerra amanhã';
48	  return `Encerra em ${diasRestantes} dias`;
49	}
50	
51	/** Valida se uma data de fim respeita CLT Art. 445 (≤ 90 dias). */
52	export function validatePrazoExperiencia(
53	  dataInicio: string,
54	  dataFim: string,
55	): { valid: boolean; dias: number; error?: string } {
56	  const inicio = new Date(dataInicio + 'T00:00:00');
57	  const fim = new Date(dataFim + 'T00:00:00');
58	  const dias = Math.round((fim.getTime() - inicio.getTime()) / (1000 * 60 * 60 * 24));
59	
60	  if (dias <= 0) {
61	    return { valid: false, dias, error: 'Data de fim deve ser posterior à data de início.' };
62	  }
63	  if (dias > 90) {
64	    return {
65	      valid: false,
66	      dias,
67	      error: `Período de ${dias} dias excede o limite legal de 90 dias (CLT Art. 445, parágrafo único).`,
68	    };
69	  }
70	  return { valid: true, dias };
71	}
72	
73	/** Valida se prorrogação é permitida. */
74	export function validateProrrogacao(
75	  contrato: Contrato,
76	): { valid: boolean; error?: string } {
77	  if (contrato.tipo !== 'experiencia') {
78	    return { valid: false, error: 'Apenas contratos de experiência podem ser prorrogados.' };
79	  }
80	  if (contrato.prorrogacao_count >= 1) {
81	    return {
82	      valid: false,
83	      error:
84	        'CLT Art. 451 + Súmula 188 TST — apenas uma prorrogação é permitida. Contrato deve ser efetivado ou encerrado.',
85	    };
86	  }
87	  if (!contrato.clausula_prorrogacao_prevista) {
88	    return {
89	      valid: false,
90	      error:
91	        'O contrato original não previu cláusula de prorrogação. Decisão TRT-3/2015 — prorrogação só se prevista no contrato.',
92	    };
93	  }
94	  return { valid: true };
95	}
