97	/** Calcula tempo de casa em formato "X anos, Y meses". Null-safe. */
98	export function tempoDeCasa(dataAdmissao: string | null | undefined): string {
99	  if (!dataAdmissao || typeof dataAdmissao !== 'string' || dataAdmissao.length < 10) return '—';
100	  const inicio = new Date(dataAdmissao.slice(0, 10) + 'T00:00:00');
101	  if (Number.isNaN(inicio.getTime())) return '—';
102	  const today = new Date();
103	  let anos = today.getFullYear() - inicio.getFullYear();
104	  let meses = today.getMonth() - inicio.getMonth();
105	  if (today.getDate() < inicio.getDate()) meses--;
106	  if (meses < 0) {
107	    anos--;
108	    meses += 12;
109	  }
110	  if (anos === 0 && meses === 0) {
111	    const dias = Math.round((today.getTime() - inicio.getTime()) / (1000 * 60 * 60 * 24));
112	    return `${dias} dia${dias === 1 ? '' : 's'}`;
113	  }
114	  if (anos === 0) return `${meses} ${meses === 1 ? 'mês' : 'meses'}`;
115	  if (meses === 0) return `${anos} ano${anos === 1 ? '' : 's'}`;
116	  return `${anos} ano${anos === 1 ? '' : 's'}, ${meses} ${meses === 1 ? 'mês' : 'meses'}`;
117	}
