38	const PROBATION_PILLS: Record<ReturnType<typeof probationAlertLevel>, string> = {
39	  safe: 'bg-blue-500/10 text-blue-700 dark:text-blue-300 border-blue-500/20',
40	  d30: 'bg-yellow-500/10 text-yellow-700 dark:text-yellow-300 border-yellow-500/20',
41	  d15: 'bg-orange-500/10 text-orange-700 dark:text-orange-300 border-orange-500/20',
42	  d7: 'bg-red-500/10 text-red-700 dark:text-red-300 border-red-500/30',
43	  overdue: 'bg-red-500/15 text-red-800 dark:text-red-200 border-red-500/40',
