52	export default function ExperienciaPage() {
53	  const navigate = useNavigate();
54	  const { employees, loading, fetchEmployees } = useEmployees({ apenas_em_experiencia: true });
55	  const [decision, setDecision] = useState<DecisionContext | null>(null);
56	
57	  // Ordenar por dias restantes (mais urgente primeiro)
58	  const sorted = useMemo(() => {
59	    return [...employees].sort((a, b) => {
60	      const da = diasAteData(a.contrato_data_fim) ?? 9999;
61	      const db = diasAteData(b.contrato_data_fim) ?? 9999;
62	      return da - db;
63	    });
64	  }, [employees]);
65	
66	  const buckets = useMemo(() => {
67	    const overdue: EmployeeListItem[] = [];
68	    const d7: EmployeeListItem[] = [];
69	    const d15: EmployeeListItem[] = [];
70	    const d30: EmployeeListItem[] = [];
71	    const safe: EmployeeListItem[] = [];
72	    sorted.forEach((e) => {
73	      const lvl = probationAlertLevel(diasAteData(e.contrato_data_fim));
74	      if (lvl === 'overdue') overdue.push(e);
75	      else if (lvl === 'd7') d7.push(e);
76	      else if (lvl === 'd15') d15.push(e);
77	      else if (lvl === 'd30') d30.push(e);
78	      else safe.push(e);
79	    });
80	    return { overdue, d7, d15, d30, safe };
81	  }, [sorted]);
82	
83	  const openDecision = async (employee: EmployeeListItem, tipo: ExperienciaDecisaoTipo) => {
84	    // Buscar contrato ativo
85	    const { data: contratos } = await supabase
86	      // eslint-disable-next-line @typescript-eslint/no-explicit-any
87	      .from('contratos' as any)
88	      .select('*')
89	      .eq('employee_id', employee.id)
90	      .eq('ativo', true)
91	      .eq('tipo', 'experiencia')
92	      .limit(1);
93	    const contrato = (contratos?.[0] as unknown as Contrato | undefined) ?? null;
94	    if (!contrato) {
95	      toast({
96	        title: 'Contrato não encontrado',
97	        description: 'Não foi possível encontrar contrato de experiência ativo.',
98	        variant: 'destructive',
99	      });
100	      return;
101	    }
102	    setDecision({ employee, contrato, tipo });
103	  };
104	
105	  return (
106	    <MommaPageLayout>
107	      <div className="relative z-10 w-full max-w-[1400px] mx-auto space-y-8 px-4 sm:px-6 py-6 animate-in fade-in duration-500">
108	        {/* Header */}
109	        <div className="flex items-center gap-3 pb-2">
110	          <Button
111	            variant="ghost"
112	            size="icon"
113	            onClick={() => navigate('/funcionarios')}
114	            className="rounded-xl hover:bg-[#57715B]/10 shrink-0"
115	          >
116	            <ArrowLeft className="h-5 w-5 text-[#57715B] dark:text-[#E6DCCF]" />
117	          </Button>
118	          <div className="hidden md:flex h-12 w-12 rounded-2xl bg-amber-500/15 dark:bg-amber-500/10 items-center justify-center shrink-0">
119	            <AlertCircle className="h-6 w-6 text-amber-700 dark:text-amber-300" />
120	          </div>
121	          <div>
122	            <h1 className="text-3xl md:text-4xl font-bold tracking-tight text-[#2D362E] dark:text-[#E6DCCF] font-serif">
123	              Período de Experiência
124	            </h1>
125	            <p className="text-xs md:text-sm text-[#8C7B6D] dark:text-[#9BA59C] font-medium tracking-widest uppercase opacity-80">
126	              CLT Art. 445/451 · Decisões pendentes da gerência
127	            </p>
128	          </div>
129	        </div>
130	
131	        {/* KPIs por urgência */}
132	        <div className="grid grid-cols-2 md:grid-cols-5 gap-4">
133	          <UrgencyCard
134	            label="Vencidos"
135	            value={buckets.overdue.length}
136	            color="#C04848"
137	            description="Decisão atrasada"
138	            highlight={buckets.overdue.length > 0}
139	          />
140	          <UrgencyCard
141	            label="≤ 7 dias"
142	            value={buckets.d7.length}
143	            color="#D9534F"
144	            description="Crítico"
145	            highlight={buckets.d7.length > 0}
146	          />
147	          <UrgencyCard
148	            label="≤ 15 dias"
149	            value={buckets.d15.length}
150	            color="#E08E45"
151	            description="Atenção"
152	          />
153	          <UrgencyCard
154	            label="≤ 30 dias"
155	            value={buckets.d30.length}
156	            color="#B49364"
157	            description="Planejar"
158	          />
159	          <UrgencyCard
160	            label="> 30 dias"
161	            value={buckets.safe.length}
162	            color="#57715B"
163	            description="No prazo"
164	          />
165	        </div>
166	
167	        {/* Lista de decisões pendentes */}
168	        <div className="bg-white/70 dark:bg-zinc-900/70 backdrop-blur-xl border border-[#57715B]/10 dark:border-white/5 rounded-[32px] p-6 shadow-lg shadow-[#57715B]/5">
169	          {loading ? (
170	            <div className="py-16 text-center text-[#8C7B6D] dark:text-[#9BA59C]">
171	              Carregando funcionários em experiência...
172	            </div>
173	          ) : sorted.length === 0 ? (
174	            <div className="py-16 flex flex-col items-center text-center space-y-3">
175	              <div className="h-14 w-14 rounded-full bg-[#57715B]/10 flex items-center justify-center">
176	                <CheckCircle2 className="h-7 w-7 text-[#57715B] dark:text-[#8FA893]" />
177	              </div>
178	              <p className="font-bold text-[#2D362E] dark:text-[#E6DCCF]">Tudo em dia!</p>
179	              <p className="text-sm text-[#8C7B6D] dark:text-[#9BA59C] max-w-md">
180	                Nenhum funcionário em período de experiência no momento.
181	              </p>
182	            </div>
183	          ) : (
184	            <div className="space-y-3">
185	              {sorted.map((emp) => {
186	                const dias = diasAteData(emp.contrato_data_fim);
187	                const lvl = probationAlertLevel(dias);
188	                return (
189	                  <div
190	                    key={emp.id}
191	                    className="flex flex-col md:flex-row md:items-center justify-between gap-4 p-4 rounded-2xl border border-[#57715B]/10 dark:border-white/5 hover:bg-[#57715B]/5 dark:hover:bg-[#E6DCCF]/5 transition-all duration-200"
192	                  >
193	                    <div className="flex items-center gap-4 flex-1 min-w-0">
194	                      <div className="h-12 w-12 rounded-2xl bg-[#57715B]/10 dark:bg-[#E6DCCF]/10 flex items-center justify-center shrink-0">
195	                        <span className="text-sm font-bold text-[#57715B] dark:text-[#E6DCCF]">
196	                          {emp.nome_completo
197	                            .split(' ')
198	                            .map((n) => n[0])
199	                            .slice(0, 2)
200	                            .join('')
201	                            .toUpperCase()}
202	                        </span>
203	                      </div>
204	                      <div className="flex-1 min-w-0">
205	                        <button
206	                          onClick={() => navigate(`/funcionarios/${emp.id}`)}
207	                          className="font-bold text-[#2D362E] dark:text-[#E6DCCF] hover:text-[#57715B] transition-colors text-left truncate w-full"
208	                        >
209	                          {emp.nome_completo}
210	                        </button>
211	                        <p className="text-xs text-[#8C7B6D] dark:text-[#9BA59C] mt-0.5">
212	                          {emp.matricula} · {emp.cargo_nome} · {emp.loja_nome}
213	                        </p>
214	                      </div>
215	                      <Badge
216	                        variant="outline"
217	                        className={`rounded-full px-3 py-0.5 text-xs whitespace-nowrap ${PROBATION_PILLS[lvl]}`}
218	                      >
219	                        {probationAlertText(dias)}
220	                      </Badge>
221	                    </div>
222	                    <div className="flex items-center gap-2 flex-wrap">
223	                      {(() => {
224	                        const naSegundaExp = (emp.prorrogacao_count ?? 0) >= 1;
225	                        return (
226	                          <>
227	                            <Button
228	                              size="sm"
229	                              onClick={() => openDecision(emp, 'efetivar')}
230	                              disabled={!naSegundaExp}
231	                              title={
232	                                naSegundaExp
233	                                  ? 'Efetivar como contrato por prazo indeterminado'
234	                                  : 'Só pode efetivar ao final da 2ª experiência. Prorrogue primeiro.'
235	                              }
236	                              className="rounded-xl bg-[#57715B] hover:bg-[#4a6450] text-white shadow-sm disabled:opacity-40 disabled:cursor-not-allowed"
237	                            >
238	                              <CheckCircle2 className="h-3.5 w-3.5 mr-1.5" />
239	                              Efetivar
240	                            </Button>
241	                            <Button
242	                              size="sm"
243	                              variant="outline"
244	                              onClick={() => openDecision(emp, 'prorrogar')}
245	                              disabled={naSegundaExp}
246	                              title={
247	                                naSegundaExp
248	                                  ? 'Já prorrogado uma vez — CLT Art. 451 permite só uma'
249	                                  : 'Prorrogar para 2ª experiência (CLT Art. 445)'
250	                              }
251	                              className="rounded-xl border-[#B49364]/30 text-[#7a5f3a] dark:text-[#C5A065] hover:bg-[#B49364]/10 disabled:opacity-40 disabled:cursor-not-allowed"
252	                            >
253	                              <CalendarPlus className="h-3.5 w-3.5 mr-1.5" />
254	                              Prorrogar
255	                            </Button>
256	                          </>
257	                        );
258	                      })()}
259	                      <Button
260	                        size="sm"
261	                        variant="outline"
262	                        onClick={() => openDecision(emp, 'encerrar')}
263	                        className="rounded-xl border-red-500/30 text-red-700 dark:text-red-300 hover:bg-red-500/10"
264	                      >
265	                        <XCircle className="h-3.5 w-3.5 mr-1.5" />
266	                        Encerrar
267	                      </Button>
268	                    </div>
269	                  </div>
270	                );
271	              })}
272	            </div>
273	          )}
274	        </div>
275	      </div>
276	
277	      {decision && (
278	        <DecisionDialog
279	          context={decision}
280	          onClose={() => setDecision(null)}
