291	function UrgencyCard({
292	  label,
293	  value,
294	  color,
295	  description,
296	  highlight = false,
297	}: {
298	  label: string;
299	  value: number;
300	  color: string;
301	  description: string;
302	  highlight?: boolean;
303	}) {
304	  return (
305	    <div
306	      className={`bg-white/70 dark:bg-zinc-900/70 backdrop-blur-xl border rounded-[24px] p-4 shadow-sm transition-all ${
307	        highlight
308	          ? 'border-red-500/30 shadow-red-500/10'
309	          : 'border-[#57715B]/10 dark:border-white/5'
310	      }`}
311	    >
312	      <p className="text-xs uppercase tracking-widest font-medium text-[#8C7B6D] dark:text-[#9BA59C] opacity-80">
313	        {label}
314	      </p>
315	      <p className="text-3xl font-bold mt-1.5 font-serif" style={{ color }}>
316	        {value}
317	      </p>
318	      <p className="text-xs text-[#8C7B6D]/70 dark:text-[#9BA59C]/70 mt-0.5">{description}</p>
319	    </div>
