321	}
322	
323	function DecisionDialog({
324	  context,
325	  onClose,
326	  onSuccess,
327	}: {
328	  context: DecisionContext;
329	  onClose: () => void;
330	  onSuccess: () => void;
331	}) {
332	  const { employee, contrato, tipo } = context;
333	  const [justificativa, setJustificativa] = useState('');
334	  const [novaDataFim, setNovaDataFim] = useState('');
335	  const [submitting, setSubmitting] = useState(false);
336	
337	  // Validações específicas
338	  const prorrogacaoCheck = useMemo(() => {
339	    if (tipo !== 'prorrogar') return { valid: true };
340	    return validateProrrogacao(contrato);
341	  }, [tipo, contrato]);
342	
343	  const novaDataCheck = useMemo(() => {
344	    if (tipo !== 'prorrogar' || !novaDataFim) return { valid: false, dias: 0 };
345	    return validatePrazoExperiencia(contrato.data_inicio, novaDataFim);
346	  }, [tipo, novaDataFim, contrato.data_inicio]);
347	
348	  const justificativaObrigatoria = tipo !== 'efetivar';
349	  const formValido =
350	    prorrogacaoCheck.valid &&
351	    (tipo !== 'prorrogar' || (novaDataFim && novaDataCheck.valid)) &&
352	    (!justificativaObrigatoria || justificativa.trim().length > 0);
353	
354	  // Valor inicial sugerido para nova data fim (30 dias depois do fim da 1ª, contando o próprio dia do fim)
355	  useEffect(() => {
356	    if (tipo === 'prorrogar' && contrato.data_fim_inicial && !novaDataFim) {
357	      const sugerido = new Date(contrato.data_fim_inicial + 'T00:00:00');
358	      sugerido.setDate(sugerido.getDate() + 30);
359	      // Mas não pode passar de 90 dias do início
360	      const maxFim = new Date(contrato.data_inicio + 'T00:00:00');
361	      maxFim.setDate(maxFim.getDate() + 90);
362	      const final = sugerido > maxFim ? maxFim : sugerido;
363	      setNovaDataFim(final.toISOString().slice(0, 10));
364	    }
365	  }, [tipo, contrato, novaDataFim]);
366	
367	  const handleSubmit = async () => {
368	    if (!formValido) return;
369	    setSubmitting(true);
370	    try {
371	      // 1) Insere registro em experiencia_decisoes
372	      const { error: errDecisao } = await supabase
373	        // eslint-disable-next-line @typescript-eslint/no-explicit-any
374	        .from('experiencia_decisoes' as any)
375	        // eslint-disable-next-line @typescript-eslint/no-explicit-any
376	        .insert({
377	          contrato_id: contrato.id,
378	          employee_id: employee.id,
379	          tipo,
380	          decidido_por: (await supabase.auth.getUser()).data.user?.id,
381	          justificativa: justificativa.trim() || null,
382	          metadata: tipo === 'prorrogar' ? { nova_data_fim: novaDataFim } : null,
383	        // eslint-disable-next-line @typescript-eslint/no-explicit-any
384	        } as any);
385	      if (errDecisao) throw errDecisao;
386	
387	      // 2) Atualiza contrato + employee conforme decisão
388	      if (tipo === 'efetivar') {
389	        await supabase
390	          // eslint-disable-next-line @typescript-eslint/no-explicit-any
391	          .from('contratos' as any)
392	          // eslint-disable-next-line @typescript-eslint/no-explicit-any
393	          .update({ ativo: false } as any)
394	          .eq('id', contrato.id);
395	        await supabase
396	          // eslint-disable-next-line @typescript-eslint/no-explicit-any
397	          .from('contratos' as any)
398	          // eslint-disable-next-line @typescript-eslint/no-explicit-any
399	          .insert({
400	            employee_id: employee.id,
401	            tipo: 'indeterminado',
