1	/**
2	 * Hook de listagem de funcionários (employees) com filtros.
3	 *
4	 * Faz join com cargos, lojas e contrato ativo (para mostrar prazo de experiência).
5	 */
6	
7	import { useCallback, useEffect, useState } from 'react';
8	import { supabase } from '@/integrations/supabase/client';
9	import { toast } from '@/shared/hooks/use-toast';
10	import { isBirthdayInMonth } from '@/shared/lib/birthday';
11	import type { EmployeeFilters, EmployeeListItem, Contrato } from '../types';
12	import { proximoFimContrato } from '../lib/probation';
13	
14	interface RawEmployeeRow {
15	  id: string;
16	  matricula: string;
17	  user_id: string | null;
18	  manager_id: string | null;
19	  loja_id: number;
20	  cargo_id: string;
21	  nome_completo: string;
22	  nome_social: string | null;
23	  cpf: string;
24	  rg: string | null;
25	  data_nascimento: string;
26	  genero: 'M' | 'F' | 'NB' | 'prefiro_nao_informar' | null;
27	  estado_civil: string | null;
28	  nacionalidade: string | null;
29	  email_corporativo: string | null;
30	  email_pessoal: string | null;
31	  telefone_celular: string | null;
32	  telefone_emergencia: string | null;
33	  contato_emergencia_nome: string | null;
34	  endereco_cep: string | null;
35	  endereco_logradouro: string | null;
36	  endereco_numero: string | null;
37	  endereco_complemento: string | null;
38	  endereco_bairro: string | null;
39	  endereco_cidade: string | null;
40	  endereco_uf: string | null;
41	  salario_base: number | null;
42	  conta_bancaria: Record<string, unknown> | null;
43	  regime: string;
44	  status: string;
45	  data_admissao: string;
46	  data_demissao: string | null;
47	  motivo_demissao: string | null;
48	  divulgar_aniversario: string;
49	  mostrar_ano_nascimento: boolean;
50	  data_descarte_planejada: string | null;
51	  foto_url: string | null;
52	  created_at: string;
53	  updated_at: string;
54	  deleted_at: string | null;
55	  cargos?: { nome: string; area: string } | null;
56	  lojas?: { nome: string } | null;
57	  contratos?: Contrato[] | null;
58	}
59	
60	export function useEmployees(filters: EmployeeFilters = {}) {
61	  const [employees, setEmployees] = useState<EmployeeListItem[]>([]);
62	  const [loading, setLoading] = useState(true);
63	
64	  const fetchEmployees = useCallback(async () => {
65	    setLoading(true);
66	    try {
67	      let query = supabase
68	        // eslint-disable-next-line @typescript-eslint/no-explicit-any
69	        .from('employees' as any)
70	        .select(
71	          `
72	            *,
73	            cargos:cargo_id(nome, area),
74	            lojas:loja_id(nome),
75	            contratos!inner(*)
76	          `,
77	        )
78	        .is('deleted_at', null)
79	        .eq('contratos.ativo', true);
80	
81	      if (filters.loja_id != null) {
82	        query = query.eq('loja_id', filters.loja_id);
83	      }
84	      if (filters.cargo_id) {
85	        query = query.eq('cargo_id', filters.cargo_id);
86	      }
87	      if (filters.status) {
88	        query = query.eq('status', filters.status);
89	      }
90	      if (filters.apenas_em_experiencia) {
91	        query = query.eq('status', 'probation');
92	      }
93	      if (filters.search) {
94	        query = query.or(
95	          `nome_completo.ilike.%${filters.search}%,matricula.ilike.%${filters.search}%`,
96	        );
97	      }
98	      if (filters.aniversariantes_mes != null) {
99	        // PG: extract month from date
100	        // Filtragem direta via SQL — usamos rpc se necessário; no client filtramos depois.
101	      }
102	
103	      query = query.order('nome_completo', { ascending: true });
104	
105	      const { data, error } = await query;
106	      if (error) throw error;
107	
108	      const rows = (data ?? []) as unknown as RawEmployeeRow[];
109	      let mapped: EmployeeListItem[] = rows.map((row) => {
110	        const contratoAtivo = row.contratos?.find((c) => c.ativo) ?? row.contratos?.[0] ?? null;
111	        return {
112	          ...row,
113	          regime: row.regime as EmployeeListItem['regime'],
114	          status: row.status as EmployeeListItem['status'],
115	          divulgar_aniversario: row.divulgar_aniversario as EmployeeListItem['divulgar_aniversario'],
116	          cargo_nome: row.cargos?.nome ?? null,
117	          cargo_area: (row.cargos?.area as EmployeeListItem['cargo_area']) ?? null,
118	          loja_nome: row.lojas?.nome ?? null,
119	          contrato_tipo: contratoAtivo?.tipo ?? null,
120	          contrato_data_fim: contratoAtivo ? proximoFimContrato(contratoAtivo) : null,
121	          prorrogacao_count: contratoAtivo?.prorrogacao_count ?? null,
122	        };
123	      });
124	
125	      if (filters.aniversariantes_mes != null) {
126	        mapped = mapped.filter((e) => isBirthdayInMonth(e.data_nascimento, filters.aniversariantes_mes!));
127	      }
128	
129	      setEmployees(mapped);
130	    } catch (err) {
131	      // eslint-disable-next-line no-console
132	      console.error('[useEmployees] fetch error', err);
133	      toast({
134	        title: 'Erro',
135	        description: 'Não foi possível carregar a lista de funcionários.',
136	        variant: 'destructive',
137	      });
138	      setEmployees([]);
139	    } finally {
140	      setLoading(false);
141	    }
142	  }, [
143	    filters.loja_id,
144	    filters.cargo_id,
145	    filters.status,
146	    filters.search,
147	    filters.apenas_em_experiencia,
148	    filters.aniversariantes_mes,
149	  ]);
150	
151	  useEffect(() => {
152	    fetchEmployees();
153	  }, [fetchEmployees]);
154	
155	  return { employees, loading, fetchEmployees };
156	}
