26	        execute: (data) => {
27	          if (data?.search !== undefined) iface.setSearch(String(data.search));
28	          if (data?.status !== undefined) {
29	            iface.setStatusFilter(data.status as EmployeeStatus | 'todos');
30	          }
31	          if (data?.cargo_id !== undefined) iface.setCargoFilter(String(data.cargo_id));
32	        },
33	      },
34	      funcionarios_em_experiencia: {
35	        id: 'funcionarios_em_experiencia',
36	        description:
37	          'Filtrar para mostrar apenas funcionários em período de experiência (probation).',
38	        execute: () => {
39	          iface.setStatusFilter('probation');
40	          iface.setAniversariantes(false);
41	          iface.setSearch('');
42	          iface.setCargoFilter('todos');
43	        },
44	      },
45	    }),
46	    [iface],
47	  );
48	
49	  useMiaActions('/funcionarios', handlers);
50	}
